import timefrom Sengo1 import *from mpython import *from machine import UARTuart1 = UART(1, baudrate=115200, tx=Pin.P14, rx=Pin.P13)sengo1 = Sengo1(0x60)# 自定义函数def UART():  global my_variable, row, column, x, y, i, j, flag, switch  sengo1.begin(uart1)def I2C():  global my_variable, row, column, x, y, i, j, flag, switch  sengo1.begin(i2c)def Flag1():  global my_variable, row, column, x, y, i, j, flag, switch  if (switch == 0):    switch = 1    sengo1.SetParam(sengo1_vision_e.kVisionColor,[25, 25, 6, 8, 1])  else:    switch = 0    sengo1.SetParam(sengo1_vision_e.kVisionColor,[75, 75, 6, 8, 1])  time.sleep(0.1)  Display()def Flag2():  global my_variable, row, column, x, y, i, j, flag, switch  switch = (switch + 1)  if (switch == 4):    switch = 0  if (switch == 0):    i = 1    for index in range(column):      x = (round((i * (100 / (column + 1)))))      y = 50      sengo1.SetParam(sengo1_vision_e.kVisionColor,[x, y, 6, 8, 1])      time.sleep(0.1)      Display()      i = (i + 1)  if (switch == 1):    i = 1    for index in range(column):      x = (round((i * (100 / (column + 1)))))      y = (100 - x)      sengo1.SetParam(sengo1_vision_e.kVisionColor,[x, y, 6, 8, 1])      time.sleep(0.1)      Display()      i = (i + 1)  if (switch == 2):    i = 1    for index in range(column):      y = (round((i * (100 / (column + 1)))))      x = 50      sengo1.SetParam(sengo1_vision_e.kVisionColor,[x, y, 6, 8, 1])      time.sleep(0.1)      Display()      i = (i + 1)  if (switch == 3):    i = 1    for index in range(column):      x = (round((i * (100 / (column + 1)))))      y = x      sengo1.SetParam(sengo1_vision_e.kVisionColor,[x, y, 6, 8, 1])      time.sleep(0.1)      Display()      i = (i + 1)def Flag3():  global my_variable, row, column, x, y, i, j, flag, switch  # 切换行  for i in range(1, (row + 1), 1):    y = (i * (round((100 / (row + 1)))))    # 切换列    for j in range(1, (column + 1), 1):      oled.fill_rect(48,16,32,16,0)      oled.show()      oled.DispChar((str((j + (row * (i - 1))))), 48, 16, 1)      oled.show()      x = (j * (round((100 / (column + 1)))))      sengo1.SetParam(sengo1_vision_e.kVisionColor,[x, y, 6, 8, 1])      # 等待参数生效后新的识别结果产出，该时间间隔不得低于该算法识别1帧所花费的时间，可以通过算法开启后，屏幕下方的帧率进行推算      time.sleep(0.1)      Display()def Display():  global my_variable, row, column, x, y, i, j, flag, switch  # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。  # Sengo最多输出1个识别结果。  if ((sengo1.GetValue(sengo1_vision_e.kVisionColor, sentry_obj_info_e.kStatus)) > 0):    oled.fill_rect(48,32,48,16,0)    oled.show()    if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorBlack):      oled.DispChar("Black", 48, 32, 1)    if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorWhite):      oled.DispChar("White", 48, 32, 1)    if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorRed):      oled.DispChar("Red", 48, 32, 1)    if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorGreen):      oled.DispChar("Green", 48, 32, 1)    if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorBlue):      oled.DispChar("Blue", 48, 32, 1)    if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorYellow):      oled.DispChar("Yellow", 48, 32, 1)    oled.show()    time.sleep(0.1)# 事件回调函数def on_button_a_down(_):  time.sleep_ms(10)  if button_a.value() == 1: return  global flag  flag = (flag + 1)  if (flag == 4):    flag = 1button_a.irq(trigger=Pin.IRQ_FALLING, handler=on_button_a_down)flag = 0switch = 0# 设置识别点的总行数，根据需要自行修改row = 5# 设置识别点的总列数，根据需要自行修改column = 5x = 0y = 0i = 0j = 0# 等待Sengo1完成初始化，此延时不可以去掉，避免Sengo1初始化尚未完成，主控板已经发送指令time.sleep(2)I2C()# 1、算法的默认参数设置，如无需更改参数，则可移除本代码块；# 2、只有颜色识别与色块检测两种算法需要设置参数；# 3、Sengo1图像的长宽比为4:3，当宽高值设为3:4时，识别区域为正方形；当宽高值设为1:1时，识别区域为长方形sengo1.SetParam(sengo1_vision_e.kVisionColor,[50, 50, 3, 4, 1])# 1、参考文档# https://tosee.readthedocs.io/zh/latest/Sentry1/Vision/index.html#chapter-vs1-vision-color-index# 2、参考视频（注：Sengo1与Sentry1是两款产品）# https://www.bilibili.com/video/BV1MV4y1f7L2/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 3、颜色识别算法常见应用：色块密码盘（魔方的一个面，需要识别点与魔方的每个色块一一对应）；红绿灯识别建议采用色块检测算法# 4、Sengo1每次只能运行一种识别算法；sengo1.VisionBegin(sengo1_vision_e.kVisionColor)oled.DispChar("Algo: Color", 0, (1-1)*16, 1)oled.DispChar("Point#: ", 0, 16, 1)oled.DispChar("Color: ", 0, 32, 1)oled.show()while True:  if (flag == 0):    Display()  if (flag == 1):    Flag1()  if (flag == 2):    Flag2()  if (flag == 3):    Flag3()